import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[65536];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = read();
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        int e = scanner.nextInt();
        if (e == -1) return;
        int m = scanner.nextInt();
        int d = scanner.nextInt();

        int[] sameX = new int[m];
        int[] sameY = new int[m];
        for (int i = 0; i < m; i++) {
            sameX[i] = scanner.nextInt();
            sameY[i] = scanner.nextInt();
        }

        int[] diffU = new int[d];
        int[] diffV = new int[d];
        for (int i = 0; i < d; i++) {
            diffU[i] = scanner.nextInt();
            diffV[i] = scanner.nextInt();
        }

        int[] group = new int[e + 1];
        int numGroups = e / 3;
        for (int g = 1; g <= numGroups; g++) {
            int s1 = scanner.nextInt();
            int s2 = scanner.nextInt();
            int s3 = scanner.nextInt();
            group[s1] = g;
            group[s2] = g;
            group[s3] = g;
        }

        int violations = 0;

        for (int i = 0; i < m; i++) {
            if (group[sameX[i]] != group[sameY[i]]) {
                violations++;
            }
        }

        for (int i = 0; i < d; i++) {
            if (group[diffU[i]] == group[diffV[i]]) {
                violations++;
            }
        }

        System.out.println(violations);
    }
}
